  "devolvedParliaments": [
    {
      "id": "scottish-parliament",
      "name": "Scottish Parliament",
      "country": "Scotland",
      "governanceModel": "Devolved parliament and government with broad legislative and executive responsibility for devolved matters.",
      "legislativeScope": "Health, education, justice, prisons, courts, local government, housing, transport and other devolved public services.",
      "fiscalScope": "Income tax rates and bands, property taxes, certain welfare benefits and major public service budgets within devolved competence.",
      "limitations": "Reserved matters include defence, foreign policy, monarchy, currency, VAT, corporation tax, National Insurance and macroeconomic policy.",
      "lastUpdated": "2026-05-16",
      "sourceIds": [
        "source-workbook"
      ]
    },
    {
      "id": "senedd-cymru",
      "name": "Senedd Cymru",
      "country": "Wales",
      "governanceModel": "Devolved parliament and Welsh Government with legislative and executive responsibility for devolved Welsh policy areas.",
      "legislativeScope": "Health, education, local government, transport, housing, environment, agriculture and economic development.",
      "fiscalScope": "Devolved taxes including Land Transaction Tax and Landfill Disposals Tax, plus limited Welsh Rate of Income Tax variation.",
      "limitations": "Does not control policing, courts, prisons, defence, foreign affairs, monetary policy, major welfare benefits, VAT, National Insurance or employment law.",
      "lastUpdated": "2026-05-16",
      "sourceIds": [
        "source-workbook"
      ]
    },
    {
      "id": "northern-ireland-assembly",
      "name": "Northern Ireland Assembly",
      "country": "Northern Ireland",
      "governanceModel": "Devolved assembly and executive operating through mandatory cross-community power sharing.",
      "legislativeScope": "Health, education, agriculture, environment, housing, transport, justice, policing and social security administration.",
      "fiscalScope": "Substantial block grant funding and legal power to set corporation tax, although that power has not been fully used in practice.",
      "limitations": "Governance depends on cross-community agreement and reserved matters include defence, national security, foreign policy, immigration, the Crown, VAT, National Insurance and most major UK-wide taxes.",
      "lastUpdated": "2026-05-16",
      "sourceIds": [
        "source-workbook"
      ]
    }
  ],
